	private static Holder<SoundEvent> music(String name, Holder<SoundEvent> sound) {
		MUSIC.put(name, sound);
		return sound;
	}

	/** A music track by its name in tools/audio/hellsounds.py ("limbo", "minos_2"), or null. */
	@Nullable
	public static Holder<SoundEvent> music(String name) {
		return MUSIC.get(name);
	}
